function demonCopyRows(grid,rows,row,col){for(let y=0;y<rows.length;y++){for(let x=0;x<rows[y].length;x++){if(rows[y][x]!=='.') grid[row+y][col+x]=rows[y][x];}}}
function demonPaintDisc(grid,cx,cy,radius,ch){for(let y=Math.floor(cy-radius);y<=Math.ceil(cy+radius);y++){for(let x=Math.floor(cx-radius);x<=Math.ceil(cx+radius);x++){if(y<0||x<0||y>=grid.length||x>=grid[0].length) continue;if((x-cx)*(x-cx)+(y-cy)*(y-cy)<=radius*radius+0.5){grid[y][x]=ch;}}}}
function demonPaintLine(grid,x1,y1,x2,y2,radius,ch){const steps=Math.max(Math.abs(x2-x1),Math.abs(y2-y1),1);for(let i=0;i<=steps;i++){const k=i/steps;demonPaintDisc(grid,Math.round(x1+(x2-x1)*k),Math.round(y1+(y2-y1)*k),radius,ch);}}
